/**
 * FILE: concept_1_smart_digital_wallet.js
 * THEME: Finance & Investment — Smart Digital Wallet & Protected Investment Ecosystem
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phase for 100% mathematically seamless 20s looping
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Color Palette (Crisp Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    phoneFrame: '#22C55E',
    phoneFrameShade: '#16A34A',
    phoneScreen: '#1D63B8',
    phoneScreenDark: '#154E96',
    cardGreen: '#2BD980',
    cardGreenDark: '#1FB868',
    accentOrange: '#FF8A3D',
    accentOrangeDark: '#E06D22',
    accentBlue: '#38BDF8',
    accentBlueMid: '#0284C7',
    accentBlueDark: '#0369A1',
    goldLight: '#FDE047',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    billLight: '#86EFAC',
    billMid: '#4ADE80',
    billDark: '#15803D',
    redCoral: '#F87171',
    slateDark: '#334155',
    slateMid: '#64748B'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  // Ensure crisp, artifact-free vector rendering with zero glow
  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem (No system font dependency)
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 14 * scaleSize;
    const h = 22 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    // Top curve of S
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    // Vertical spine
    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Checkmark
  function drawCheckmark(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX - size * 0.65, centerY + size * 0.05);
    ctx.lineTo(centerX - size * 0.15, centerY + size * 0.55);
    ctx.lineTo(centerX + size * 0.75, centerY - size * 0.50);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Lock Icon
  function drawLockIcon(centerX, centerY, size, bodyColor, outlineColor, lineW) {
    ctx.save();
    // Shackle
    ctx.strokeStyle = outlineColor;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.arc(centerX, centerY - size * 0.22, size * 0.36, Math.PI, 0, false);
    ctx.lineTo(centerX + size * 0.36, centerY + size * 0.05);
    ctx.moveTo(centerX - size * 0.36, centerY - size * 0.22);
    ctx.lineTo(centerX - size * 0.36, centerY + size * 0.05);
    ctx.stroke();

    // Body
    roundedRectPath(
      centerX - size * 0.58,
      centerY - size * 0.05,
      size * 1.16,
      size * 0.88,
      size * 0.22
    );
    fillAndStroke(bodyColor, outlineColor, lineW);

    // Keyhole dot
    ctx.fillStyle = outlineColor;
    ctx.beginPath();
    ctx.arc(centerX, centerY + size * 0.36, size * 0.13, 0, tau);
    ctx.fill();
    ctx.restore();
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE & NON-INTERSECTING DATA BRIDGES
  // =========================================================================
  const baseLineY = cy + 435 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;

  // Main Ground Platform Line (Segmented with clean spacing)
  ctx.beginPath();
  ctx.moveTo(cx - 720 * s, baseLineY);
  ctx.lineTo(cx + 720 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks (strictly non-overlapping)
  const tickOffset = Math.sin(p2) * 8 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 795 * s - tickOffset, baseLineY);
  ctx.lineTo(cx - 745 * s - tickOffset, baseLineY);
  ctx.moveTo(cx + 745 * s + tickOffset, baseLineY);
  ctx.lineTo(cx + 795 * s + tickOffset, baseLineY);
  ctx.stroke();

  // Sub-base accent bar
  ctx.beginPath();
  ctx.moveTo(cx - 320 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 320 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Data Corridor Bridges (Between Center Phone and Left/Right Modules)
  // Left Corridor: x from -248*s to -186*s | Right Corridor: x from +186*s to +248*s
  const bridgeYs = [-190 * s, 185 * s];
  for (let i = 0; i < bridgeYs.length; i++) {
    const by = cy + bridgeYs[i];
    // Left bridge track
    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = thinStrokeW;
    ctx.beginPath();
    ctx.moveTo(cx - 246 * s, by);
    ctx.lineTo(cx - 188 * s, by);
    ctx.stroke();

    // Right bridge track
    ctx.beginPath();
    ctx.moveTo(cx + 188 * s, by);
    ctx.lineTo(cx + 246 * s, by);
    ctx.stroke();

    // Traveling data packet pill on Left Bridge (strictly inside [-240*s, -194*s])
    const packetPhaseL = (sceneProgress * 4 + i * 0.5) % 1;
    const pxL = cx - 238 * s + packetPhaseL * 42 * s;
    ctx.fillStyle = i === 0 ? COL.cardGreen : COL.accentBlue;
    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = 2.5 * s;
    ctx.beginPath();
    ctx.arc(pxL, by, 6.5 * s, 0, tau);
    ctx.fill();
    ctx.stroke();

    // Traveling data packet pill on Right Bridge (strictly inside [+194*s, +240*s])
    const packetPhaseR = (sceneProgress * 4 + 0.25 + i * 0.5) % 1;
    const pxR = cx + 196 * s + packetPhaseR * 42 * s;
    ctx.fillStyle = i === 0 ? COL.accentOrange : COL.goldMid;
    ctx.beginPath();
    ctx.arc(pxR, by, 6.5 * s, 0, tau);
    ctx.fill();
    ctx.stroke();
  }

  // =========================================================================
  // 3. LEFT-TOP ZONE: BANKNOTES & YIELD GROWTH MODULE
  // Bounding Box: x in [cx - 675*s, cx - 260*s], y in [cy - 365*s, cy - 25*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 5.5 * s;
  const ltX = cx - 665 * s;
  const ltY = cy - 350 * s + ltFloatY;
  const ltW = 400 * s;

  // 3A. Top Sub-Module: Crisp Flat Vector Dollar Banknote 1
  // Height: 122*s (y: -350*s to -228*s)
  const bill1H = 122 * s;
  roundedRectPath(ltX, ltY, ltW, bill1H, 16 * s);
  fillAndStroke(COL.billMid, COL.outline, strokeW);

  // Inner decorative border of Banknote 1
  roundedRectPath(ltX + 14 * s, ltY + 14 * s, ltW - 28 * s, bill1H - 28 * s, 10 * s);
  fillAndStroke(COL.billLight, COL.outline, thinStrokeW);

  // Corner serial badges inside Banknote 1 (non-overlapping)
  const cornerW = 36 * s;
  const cornerH = 18 * s;
  roundedRectPath(ltX + 26 * s, ltY + 26 * s, cornerW, cornerH, 5 * s);
  fillAndStroke(COL.billDark, null, 0);
  roundedRectPath(ltX + ltW - 62 * s, ltY + 26 * s, cornerW, cornerH, 5 * s);
  fillAndStroke(COL.billDark, null, 0);
  roundedRectPath(ltX + 26 * s, ltY + bill1H - 44 * s, cornerW, cornerH, 5 * s);
  fillAndStroke(COL.billDark, null, 0);
  roundedRectPath(ltX + ltW - 62 * s, ltY + bill1H - 44 * s, cornerW, cornerH, 5 * s);
  fillAndStroke(COL.billDark, null, 0);

  // Center Medallion of Banknote 1
  const med1X = ltX + ltW * 0.5;
  const med1Y = ltY + bill1H * 0.5;
  const medPulse = 1 + Math.sin(p4) * 0.035;
  ctx.beginPath();
  ctx.arc(med1X, med1Y, 34 * s * medPulse, 0, tau);
  fillAndStroke(COL.phoneFrameShade, COL.outline, thinStrokeW);

  drawVectorDollar(med1X, med1Y, 1.05 * s, COL.surfaceWhite, 4 * s);

  // Side security bars inside Banknote 1
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(ltX + 85 * s, med1Y - 10 * s);
  ctx.lineTo(ltX + 140 * s, med1Y - 10 * s);
  ctx.moveTo(ltX + 85 * s, med1Y + 10 * s);
  ctx.lineTo(ltX + 140 * s, med1Y + 10 * s);
  ctx.moveTo(ltX + ltW - 140 * s, med1Y - 10 * s);
  ctx.lineTo(ltX + ltW - 85 * s, med1Y - 10 * s);
  ctx.moveTo(ltX + ltW - 140 * s, med1Y + 10 * s);
  ctx.lineTo(ltX + ltW - 85 * s, med1Y + 10 * s);
  ctx.stroke();

  // 3B. Bottom Sub-Module in Left-Top Zone: Yield Analytics & Treasury Strip
  // Separated by 22*s vertical margin -> y starts at ltY + 144*s, height 160*s (ends at -46*s)
  const yieldY = ltY + 144 * s;
  const yieldH = 160 * s;
  roundedRectPath(ltX, yieldY, ltW, yieldH, 18 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Left vertical accent badge inside Yield Card
  roundedRectPath(ltX + 18 * s, yieldY + 18 * s, 110 * s, yieldH - 36 * s, 12 * s);
  fillAndStroke(COL.cardGreen, COL.outline, thinStrokeW);

  // Animated Upward Arrow inside green badge
  const arrowShiftY = Math.sin(p4) * 4 * s;
  drawUpArrow(ltX + 73 * s, yieldY + yieldH * 0.5 + arrowShiftY, 34 * s, COL.outline, 5 * s);

  // 5 Equalizer / Yield Bars on the right side of Yield Card (x from ltX + 152*s to ltX + 375*s)
  const barAreaX = ltX + 154 * s;
  const barBaseY = yieldY + yieldH - 22 * s;
  const maxBarH = yieldH - 44 * s;
  const barW = 28 * s;
  const barGap = 18 * s;

  for (let b = 0; b < 5; b++) {
    const bx = barAreaX + b * (barW + barGap);
    const wave = 0.55 + 0.35 * Math.sin(p2 - b * 0.65) + b * 0.04;
    const bh = Math.max(28 * s, Math.min(maxBarH, maxBarH * wave));
    const by = barBaseY - bh;

    // Background track slot
    roundedRectPath(bx, yieldY + 22 * s, barW, maxBarH, 7 * s);
    fillAndStroke(COL.surfaceLight, null, 0);

    // Active animated bar
    const barCol = b === 4 ? COL.goldMid : (b >= 2 ? COL.cardGreen : COL.accentBlue);
    roundedRectPath(bx, by, barW, bh, 7 * s);
    fillAndStroke(barCol, COL.outline, thinStrokeW);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: CYBER SECURITY SHIELD MODULE
  // Bounding Box: x in [cx - 665*s, cx - 265*s], y in [cy + 15*s, cy + 385*s]
  // Completely separated from Left-Top Zone by 60*s vertical gap
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 5.5 * s;
  const shieldCX = cx - 465 * s;
  const shieldCY = cy + 195 * s + lbFloatY;
  const shieldW = 310 * s;
  const shieldH = 340 * s;

  // Helper: Draw Precision Shield Path around (scx, scy)
  function shieldPath(scx, scy, sw, sh) {
    const topY = scy - sh * 0.48;
    const botY = scy + sh * 0.52;
    const sideX = sw * 0.5;
    ctx.beginPath();
    ctx.moveTo(scx, topY);
    // Top-right curve to shoulder
    ctx.quadraticCurveTo(scx + sideX * 0.55, topY + sh * 0.06, scx + sideX, topY + sh * 0.08);
    // Right side tapering down to bottom tip
    ctx.bezierCurveTo(
      scx + sideX, scy + sh * 0.08,
      scx + sideX * 0.62, scy + sh * 0.36,
      scx, botY
    );
    // Left side tapering up from bottom tip
    ctx.bezierCurveTo(
      scx - sideX * 0.62, scy + sh * 0.36,
      scx - sideX, scy + sh * 0.08,
      scx - sideX, topY + sh * 0.08
    );
    // Top-left shoulder back to top peak
    ctx.quadraticCurveTo(scx - sideX * 0.55, topY + sh * 0.06, scx, topY);
    ctx.closePath();
  }

  // Outer Shield Bezel
  shieldPath(shieldCX, shieldCY, shieldW, shieldH);
  fillAndStroke(COL.accentBlue, COL.outline, strokeW);

  // Inner Shield Core (Inset by 0.80 scale)
  shieldPath(shieldCX, shieldCY + 2 * s, shieldW * 0.78, shieldH * 0.78);
  fillAndStroke(COL.accentBlueMid, COL.outline, thinStrokeW);

  // Clip inside Inner Shield Core for clean internal scan bar & PCB circuits
  ctx.save();
  shieldPath(shieldCX, shieldCY + 2 * s, shieldW * 0.76, shieldH * 0.76);
  ctx.clip();

  // Right-half darker vector shading inside shield core
  ctx.fillStyle = COL.accentBlueDark;
  ctx.fillRect(shieldCX, shieldCY - shieldH * 0.5, shieldW * 0.5, shieldH);

  // Clean Flat Vector Scan Band (Zero glow, strictly crisp semi-transparent stripe)
  const scanNorm = Math.sin(p2);
  const scanY = shieldCY + scanNorm * (shieldH * 0.28);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.16)';
  ctx.fillRect(shieldCX - shieldW * 0.5, scanY - 14 * s, shieldW, 28 * s);
  ctx.restore();

  // Symmetric PCB Circuit Traces & Nodes inside Shield Core (Strictly non-overlapping)
  const nodeOffsets = [
    { sx: -72, sy: -65, mx: -48, my: -65 },
    { sx: -82, sy: -5,  mx: -54, my: -5 },
    { sx: -58, sy: 55,  mx: -38, my: 55 },
    { sx: 72,  sy: -65, mx: 48,  my: -65 },
    { sx: 82,  sy: -5,  mx: 54,  my: -5 },
    { sx: 58,  sy: 55,  mx: 38,  my: 55 }
  ];

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  for (let n = 0; n < nodeOffsets.length; n++) {
    const nd = nodeOffsets[n];
    const nx = shieldCX + nd.sx * s;
    const ny = shieldCY + nd.sy * s;
    const mx = shieldCX + nd.mx * s;
    const my = shieldCY + nd.my * s;

    ctx.beginPath();
    ctx.moveTo(nx, ny);
    ctx.lineTo(mx, my);
    ctx.stroke();

    const activeNode = 0.5 + 0.5 * Math.sin(p4 + n * 1.05);
    const nodeR = (6.5 + activeNode * 1.5) * s;
    ctx.beginPath();
    ctx.arc(nx, ny, nodeR, 0, tau);
    fillAndStroke(activeNode > 0.6 ? COL.cardGreen : COL.surfaceWhite, COL.outline, 2.8 * s);
  }

  // Central Verification Badge Circle inside Shield
  const badgeR = 46 * s;
  ctx.beginPath();
  ctx.arc(shieldCX, shieldCY - 4 * s, badgeR, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  const checkScale = 1 + Math.sin(p4) * 0.05;
  drawCheckmark(shieldCX, shieldCY - 4 * s, 26 * s * checkScale, COL.phoneFrameShade, 6.5 * s);

  // =========================================================================
  // 5. CENTER ZONE: SMART DIGITAL WALLET SMARTPHONE HUB
  // Bounding Box: x in [cx - 175*s, cx + 175*s], y in [cy - 365*s, cy + 365*s]
  // Minimum 85*s horizontal separation from both Left and Right zones!
  // =========================================================================
  const phoneFloatY = Math.sin(p1) * 5 * s;
  const phoneW = 344 * s;
  const phoneH = 710 * s;
  const phoneX = cx - phoneW * 0.5;
  const phoneY = cy - phoneH * 0.5 + phoneFloatY;

  // Outer Smartphone Bezel
  roundedRectPath(phoneX, phoneY, phoneW, phoneH, 42 * s);
  fillAndStroke(COL.phoneFrame, COL.outline, strokeW);

  // Inner Smartphone Screen
  const scrPad = 18 * s;
  const scrX = phoneX + scrPad;
  const scrY = phoneY + scrPad;
  const scrW = phoneW - scrPad * 2;
  const scrH = phoneH - scrPad * 2;

  roundedRectPath(scrX, scrY, scrW, scrH, 28 * s);
  fillAndStroke(COL.phoneScreen, COL.outline, thinStrokeW);

  // Top Speaker & Status Bar (y: scrY + 14*s to scrY + 34*s)
  const statusY = scrY + 22 * s;
  // Speaker slot
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 32 * s, statusY);
  ctx.lineTo(cx + 12 * s, statusY);
  ctx.stroke();
  // Front camera dot
  ctx.fillStyle = COL.outline;
  ctx.beginPath();
  ctx.arc(cx + 28 * s, statusY, 3.5 * s, 0, tau);
  ctx.fill();

  // Status Icons on Top Right of Screen (Signal Bars + Battery, non-overlapping)
  for (let sb = 0; sb < 3; sb++) {
    const sbx = scrX + scrW - 68 * s + sb * 8 * s;
    const sbh = (6 + sb * 3.5) * s;
    ctx.fillStyle = COL.surfaceWhite;
    ctx.fillRect(sbx, statusY + 5 * s - sbh, 4.5 * s, sbh);
  }
  roundedRectPath(scrX + scrW - 38 * s, statusY - 7 * s, 20 * s, 12 * s, 3 * s);
  fillAndStroke(COL.cardGreen, COL.outline, 2 * s);

  // 5A. Balance Display Card inside Phone Screen (y: scrY + 42*s, height: 112*s)
  const balX = scrX + 18 * s;
  const balY = scrY + 44 * s;
  const balW = scrW - 36 * s;
  const balH = 110 * s;

  roundedRectPath(balX, balY, balW, balH, 18 * s);
  fillAndStroke(COL.cardGreen, COL.outline, thinStrokeW);

  // Balance Dollar Emblem Circle on Left of Balance Card
  const balIconCX = balX + 44 * s;
  const balIconCY = balY + balH * 0.5;
  ctx.beginPath();
  ctx.arc(balIconCX, balIconCY, 26 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);
  drawVectorDollar(balIconCX, balIconCY, 0.85 * s, COL.phoneFrameShade, 3.8 * s);

  // Animated Balance Progress & Value Bars on Right of Balance Card (Strictly separated)
  const valTrackX = balX + 86 * s;
  const valTrackW = balW - 104 * s;
  // Top label bar
  roundedRectPath(valTrackX, balY + 24 * s, valTrackW * 0.55, 12 * s, 6 * s);
  fillAndStroke(COL.phoneFrameShade, null, 0);

  // Animated main balance meter bar
  roundedRectPath(valTrackX, balY + 48 * s, valTrackW, 20 * s, 8 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, 2.5 * s);

  const fillRatio = 0.72 + 0.18 * Math.sin(p2);
  roundedRectPath(valTrackX + 3 * s, balY + 51 * s, (valTrackW - 6 * s) * fillRatio, 14 * s, 5 * s);
  fillAndStroke(COL.goldMid, null, 0);

  // Bottom mini profit pills inside Balance Card
  for (let mp = 0; mp < 3; mp++) {
    const mpx = valTrackX + mp * 58 * s;
    roundedRectPath(mpx, balY + 80 * s, 46 * s, 10 * s, 5 * s);
    fillAndStroke(mp === 0 ? COL.surfaceWhite : COL.cardGreenDark, null, 0);
  }

  // 5B. Three Quick-Action Buttons Row (y: scrY + 172*s, height: 64*s)
  // Evenly spaced across scrW with clear gaps
  const actY = scrY + 172 * s;
  const actSize = 64 * s;
  const actCenters = [cx - 88 * s, cx, cx + 88 * s];

  for (let a = 0; a < 3; a++) {
    const acx = actCenters[a];
    const acy = actY + actSize * 0.5;
    const btnWave = Math.sin(p2 - a * 1.1);
    const btnOffsetY = btnWave * 3 * s;

    const btnCol = a === 1 ? COL.accentBlue : COL.accentOrange;
    roundedRectPath(acx - actSize * 0.5, acy - actSize * 0.5 + btnOffsetY, actSize, actSize, 14 * s);
    fillAndStroke(btnCol, COL.outline, thinStrokeW);

    if (a === 0) {
      // Up-Right Transfer Arrow
      ctx.save();
      ctx.translate(acx, acy + btnOffsetY);
      ctx.rotate(Math.PI * 0.25);
      drawUpArrow(0, 0, 22 * s, COL.surfaceWhite, 4.2 * s);
      ctx.restore();
    } else if (a === 1) {
      // 4-Node Portfolio Grid Icon
      const ndDist = 10 * s;
      for (let nx = -1; nx <= 1; nx += 2) {
